import React from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Grid, Card, CardContent, CircularProgress,
  Avatar, Chip, LinearProgress, Divider, Stack,
} from '@mui/material';
import PeopleIcon from '@mui/icons-material/People';
import BusinessIcon from '@mui/icons-material/Business';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import WorkIcon from '@mui/icons-material/Work';
import AssignmentIcon from '@mui/icons-material/Assignment';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import PersonIcon from '@mui/icons-material/Person';
import { toJalali } from '../core/utils/dateUtils';
import { keyframes } from '@mui/system';

const shimmer = keyframes`0% { left: -100%; } 100% { left: 100%; }`;

const sectionColors = {
  dept: '#6366f1',
  gender: '#ec4899',
  location: '#10b981',
  contracts: '#f59e0b',
  turnover: '#3b82f6',
  age: '#8b5cf6',
};

const StatCard = ({ title, count, percent, color, icon }) => (
  <Card sx={{
    background: `linear-gradient(135deg, ${color}10, ${color}05)`,
    border: `1px solid ${color}20`,
    backdropFilter: 'blur(10px)',
    transition: 'all 0.2s ease',
    '&:hover': { transform: 'translateY(-2px)', boxShadow: `0 4px 16px ${color}15` },
  }}>
    <CardContent sx={{ py: 2 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
        <Box>
          <Typography variant="caption" color="textSecondary">{title}</Typography>
          <Typography variant="h5" fontWeight={800} sx={{ color }}>{count}</Typography>
        </Box>
        <Avatar sx={{ width: 40, height: 40, bgcolor: `${color}18`, color }}>{icon}</Avatar>
      </Box>
      {percent !== undefined && (
        <Box>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
            <Typography variant="caption" color="textSecondary">درصد از کل</Typography>
            <Typography variant="caption" fontWeight={600} sx={{ color }}>{percent}%</Typography>
          </Box>
          <LinearProgress
            variant="determinate" value={Math.min(percent, 100)}
            sx={{ height: 6, borderRadius: 3, bgcolor: `${color}15`, '& .MuiLinearProgress-bar': { bgcolor: color, borderRadius: 3 } }}
          />
        </Box>
      )}
    </CardContent>
  </Card>
);

const SectionHeader = ({ title, color, icon }) => (
  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 2 }}>
    <Avatar sx={{ width: 32, height: 32, bgcolor: `${color}18`, color }}>{icon}</Avatar>
    <Typography variant="h6" fontWeight={700}>{title}</Typography>
  </Box>
);

const ReportsPage = () => {
  const { t } = useTranslation();

  const { data: byDept, isLoading: ld1 } = useQuery({
    queryKey: ['report-dept'], queryFn: () => axiosInstance.get('/reports/employees-by-department/').then(r => r.data),
  });
  const { data: byGender, isLoading: ld2 } = useQuery({
    queryKey: ['report-gender'], queryFn: () => axiosInstance.get('/reports/employees-by-gender/').then(r => r.data),
  });
  const { data: byLocation, isLoading: ld3 } = useQuery({
    queryKey: ['report-loc'], queryFn: () => axiosInstance.get('/reports/employees-by-location/').then(r => r.data),
  });
  const { data: contracts, isLoading: ld4 } = useQuery({
    queryKey: ['report-contracts'], queryFn: () => axiosInstance.get('/reports/contracts-expiring/').then(r => r.data),
  });
  const { data: turnover, isLoading: ld5 } = useQuery({
    queryKey: ['report-turnover'], queryFn: () => axiosInstance.get('/reports/turnover-rate/').then(r => r.data),
  });
  const { data: avgAge, isLoading: ld6 } = useQuery({
    queryKey: ['report-avg-age'], queryFn: () => axiosInstance.get('/reports/average-age-experience/').then(r => r.data),
  });

  const isLoading = ld1 || ld2 || ld3 || ld4 || ld5 || ld6;

  if (isLoading) {
    return (
      <Box>
        <Typography variant="h4" fontWeight={800} gutterBottom>{t('reports.title')}</Typography>
        <Grid container spacing={2}>
          {[1,2,3,4,5,6].map(i => (
            <Grid item xs={12} md={6} key={i}>
              <Paper sx={{ p: 2, height: 200, position: 'relative', overflow: 'hidden' }}>
                <Box sx={{ position: 'absolute', top: 0, left: '-100%', width: '100%', height: '100%',
                  background: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent)',
                  animation: `${shimmer} 1.5s infinite`,
                }} />
              </Paper>
            </Grid>
          ))}
        </Grid>
      </Box>
    );
  }

  const totalEmployees = (byGender || []).reduce((sum, g) => sum + (g.count || 0), 0);

  return (
    <Box>
      {/* Header */}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 4 }}>
        <Avatar sx={{
          width: 52, height: 52,
          background: 'linear-gradient(135deg, #10b981, #059669)',
          boxShadow: '0 6px 20px rgba(16,185,129,0.35)',
        }}>
          <AssignmentIcon sx={{ fontSize: 28, color: '#fff' }} />
        </Avatar>
        <Box>
          <Typography variant="h4" fontWeight={800}>{t('reports.title')}</Typography>
          <Typography variant="body2" color="textSecondary">
            {t('table.total', { count: totalEmployees })} · {new Date().toLocaleDateString('fa-IR')}
          </Typography>
        </Box>
      </Box>

      <Grid container spacing={3}>
        {/* Turnover Rate — Top Banner */}
        <Grid item xs={12}>
          <Paper sx={{
            p: 3,
            background: `linear-gradient(135deg, ${sectionColors.turnover}15, ${sectionColors.turnover}05)`,
            border: `1px solid ${sectionColors.turnover}20`,
            display: 'flex', alignItems: 'center', gap: 3, flexWrap: 'wrap',
          }}>
            <Avatar sx={{ width: 56, height: 56, bgcolor: `${sectionColors.turnover}20`, color: sectionColors.turnover }}>
              <TrendingDownIcon sx={{ fontSize: 32 }} />
            </Avatar>
            <Box>
              <Typography variant="body2" color="textSecondary">{t('reports.turnover_rate')}</Typography>
              <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1 }}>
                <Typography variant="h3" fontWeight={800} sx={{ color: sectionColors.turnover }}>
                  {turnover?.rate || '0.00'}%
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  ({turnover?.terminated_count || 0} خروج از {turnover?.avg_employees || 0} پرسنل)
                </Typography>
              </Box>
            </Box>
          </Paper>
        </Grid>

        {/* Department Distribution */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3, height: '100%' }}>
            <SectionHeader title={t('reports.employees_by_department')} color={sectionColors.dept}
              icon={<BusinessIcon sx={{ fontSize: 18 }} />} />
            <Stack spacing={1.5}>
              {(byDept || []).slice(0, 10).map((d, i) => (
                <Box key={i}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                    <Typography variant="body2" fontWeight={500}>{d.name}</Typography>
                    <Typography variant="body2" fontWeight={600} sx={{ color: sectionColors.dept }}>{d.count} ({d.percent}%)</Typography>
                  </Box>
                  <LinearProgress variant="determinate" value={Math.min(d.percent, 100)}
                    sx={{ height: 8, borderRadius: 4, bgcolor: `${sectionColors.dept}10`,
                      '& .MuiLinearProgress-bar': { bgcolor: sectionColors.dept, borderRadius: 4 } }} />
                </Box>
              ))}
            </Stack>
          </Paper>
        </Grid>

        {/* Gender Distribution */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3, height: '100%' }}>
            <SectionHeader title={t('reports.employees_by_gender')} color={sectionColors.gender}
              icon={<PeopleIcon sx={{ fontSize: 18 }} />} />
            <Grid container spacing={2}>
              {(byGender || []).map((g, i) => (
                <Grid item xs={6} key={i}>
                  <StatCard title={g.gender} count={g.count} percent={g.percent} color={sectionColors.gender}
                    icon={<PersonIcon sx={{ fontSize: 20 }} />} />
                </Grid>
              ))}
            </Grid>
            <Divider sx={{ my: 2 }} />
            <Box sx={{ textAlign: 'center' }}>
              <Typography variant="body2" color="textSecondary">مجموع پرسنل</Typography>
              <Typography variant="h4" fontWeight={800} sx={{ color: sectionColors.gender }}>{totalEmployees}</Typography>
            </Box>
          </Paper>
        </Grid>

        {/* Location Distribution */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3 }}>
            <SectionHeader title={t('reports.employees_by_location')} color={sectionColors.location}
              icon={<LocationOnIcon sx={{ fontSize: 18 }} />} />
            <Grid container spacing={2}>
              {(byLocation || []).map((l, i) => (
                <Grid item xs={6} key={i}>
                  <StatCard title={l.name} count={l.count} color={sectionColors.location}
                    icon={<LocationOnIcon sx={{ fontSize: 20 }} />} />
                </Grid>
              ))}
            </Grid>
          </Paper>
        </Grid>

        {/* Average Age & Experience */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3 }}>
            <SectionHeader title={t('reports.average_age_experience')} color={sectionColors.age}
              icon={<TrendingDownIcon sx={{ fontSize: 18 }} />} />
            <Stack spacing={1.5}>
              {(avgAge || []).slice(0, 8).map((a, i) => (
                <Box key={i} sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="body2" fontWeight={500}>{a.department}</Typography>
                  <Box sx={{ display: 'flex', gap: 2 }}>
                    <Chip icon={<PersonIcon sx={{ fontSize: 14 }} />}
                      label={`سن: ${a.avg_age || '—'} سال`} size="small" variant="outlined"
                      sx={{ borderColor: sectionColors.age, color: sectionColors.age }} />
                    <Chip label={`سابقه: ${a.avg_experience_years || '—'} سال`} size="small" variant="outlined"
                      sx={{ borderColor: sectionColors.age, color: sectionColors.age }} />
                  </Box>
                </Box>
              ))}
              {(!avgAge || avgAge.length === 0) && <Typography color="textSecondary" variant="body2">داده‌ای موجود نیست</Typography>}
            </Stack>
          </Paper>
        </Grid>

        {/* Expiring Contracts */}
        <Grid item xs={12}>
          <Paper sx={{ p: 3 }}>
            <SectionHeader title={t('reports.contracts_expiring')} color={sectionColors.contracts}
              icon={<AssignmentIcon sx={{ fontSize: 18 }} />} />
            {(!contracts || contracts.length === 0) ? (
              <Box sx={{ textAlign: 'center', p: 3 }}>
                <Typography variant="body2" color="textSecondary">هیچ قراردادی در ۹۰ روز آینده منقضی نمی‌شود</Typography>
              </Box>
            ) : (
              <Grid container spacing={1.5}>
                {contracts.slice(0, 12).map((c, i) => (
                  <Grid item xs={12} sm={6} md={4} key={i}>
                    <Card variant="outlined" sx={{
                      background: `${sectionColors.contracts}08`,
                      border: `1px solid ${sectionColors.contracts}20`,
                    }}>
                      <CardContent sx={{ py: 1.5, display: 'flex', alignItems: 'center', gap: 1.5 }}>
                        <Avatar sx={{ width: 36, height: 36, bgcolor: sectionColors.contracts, fontSize: 14, fontWeight: 700 }}>
                          {c.full_name?.charAt(0)}
                        </Avatar>
                        <Box>
                          <Typography variant="body2" fontWeight={600}>{c.full_name}</Typography>
                          <Typography variant="caption" color="textSecondary">
                            {c.employee_id} · انقضا: {toJalali(c.contract_end_date)}
                          </Typography>
                        </Box>
                      </CardContent>
                    </Card>
                  </Grid>
                ))}
              </Grid>
            )}
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default ReportsPage;
